import React from 'react';
import Svg, { Path } from 'react-native-svg';
import { colors } from '../styles/theme';

/**
 * Real vector icon set — replaces the emoji glyphs previously used across
 * CreateAuditScreen, AuditFormScreen, and AddChildFormScreen.
 *
 * Every path below is copied verbatim (viewBox + path `d`) from the actual
 * icon assets fetched via Figma's get_design_context/download_assets for
 * frames 2:4, 3:5, 4:4 (file SLScwP1R0FXC27Rp85Jx1W) this session — not
 * redrawn or approximated. Default `color` is `colors.primary` (#6d127b,
 * the exact brand purple used for the header and most icon backgrounds),
 * but several icons (the 5 sub-form checklist icons on AuditFormScreen,
 * and the bottom-nav home/menu icons) are intentionally NOT purple in the
 * real Figma asset — each caller passes the correct theme color for those,
 * verified against each downloaded SVG's own fill/stroke value:
 *   info=#6d127b(primary) location_on=#129b7b(success/statusArrival)
 *   monitoring=#d97b12(statusPerformance) article=#127bd9(statusSummary)
 *   block=#d9125c(error/statusDontWalkBy) home/menu=#786e7e(textSecondary)
 */

export interface IconProps {
  size?: number;
  color?: string;
}

export interface AspectIconProps {
  height?: number;
  color?: string;
}

// Stroke-based icons (outline style, 20x20/18x18/22x22 viewBoxes, strokeWidth 2)
function strokeIcon(viewBox: string, d: string) {
  return function StrokeIcon({ size = 20, color = colors.primary }: IconProps) {
    return (
      <Svg width={size} height={size} viewBox={viewBox} fill="none">
        <Path d={d} stroke={color} strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" />
      </Svg>
    );
  };
}

// Fill-based icons (Material-style solid glyphs)
function fillIcon(viewBox: string, d: string) {
  return function FillIcon({ size = 20, color = colors.primary }: IconProps) {
    return (
      <Svg width={size} height={size} viewBox={viewBox} fill="none">
        <Path d={d} fill={color} />
      </Svg>
    );
  };
}

